                      ];\n}', '<?php\nclass Foo\n{\n  const\n     FOO = [\n               1\n                          ];\n}');\n\ntest('multiline class constant with semicolon on next line', '<?php\nclass Foo\n{\n    public const\n        FOO = 1\n    ;\n}', '<?php\nclass Foo\n{\n  public const\n     FOO = 1\n      ;\n}');\n\ntest('multiline class property', '<?php\nclass Foo\n{\n    public\n        $foo;\n    protected\n        $bar;\n    private\n        $baz;\n}', '<?php\nclass Foo\n{\n  public\n     $foo;\n  protected\n         $bar;\n  private\n                $baz;\n}');\n\ntest('multiline class property with default value', '<?php\nclass Foo\n{\n    public\n        $foo = 1;\n}', '<?php\nclass Foo\n{\n  public\n     $foo = 1;\n}');\n\ntest('multiline class typed property', '<?php\nclass Foo\n{\n    public\n        int $foo;\n}', '<?php\nclass Foo\n{\n  public\n     int $foo;\n}');\n\ntest('multiline class static property', '<?php\nclass Foo\n{\n    public static\n        $foo;\n    static public\n        $bar;\n}', '<?php\nclass Foo\n{\n  public static\n     $foo;\n  static public\n       $bar;\n}');\n\ntest('multiline comma-separated class properties', '<?php\nclass Foo\n{\n    public\n        $foo,\n        $bar;\n}', '<?php\nclass Foo\n{\n  public\n     $foo,\n      $bar;\n}');\n\ntest('multiline class property with array value', '<?php\nclass Foo\n{\n    public\n        $foo = [\n                  1\n                             ];\n}', '<?php\nclass Foo\n{\n  public\n     $foo = [\n               1\n                          ];\n}');\n\ntest('multiline class property with semicolon on next line', '<?php\nclass Foo\n{\n    public\n        $foo\n    ;\n}', '<?php\nclass Foo\n{\n  public\n     $foo\n      ;\n}');\n\ntest('multiline class property with var', '<?php\nclass Foo\n{\n    var\n        $foo;\n}', '<?php\nclass Foo\n{\n  var\n     $foo;\n}');\n\ntest('property with multiline array containing explicit keys', '<?php\nclass Foo\n{\n    private $foo =